import{_ as t,a0 as o,w as r,s as d,ao as e,I as i,a1 as p,A as l,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用 Elixir 語言編寫一個小遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Elixir 語言編寫一個小遊戲 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Elixir 語言編寫一個小遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Elixir 語言編寫一個小遊戲 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20201209 Program a simple game with Elixir","title":"使用 Elixir 語言編寫一個小遊戲","tag":"202104","desc":""},"relativePath":"202104/20201209 Program a simple game with Elixir.md","filePath":"[post].md"}'),u={name:"202104/20201209 Program a simple game with Elixir.md"};function g(m,s,x,T,f,h){const a=o("Link");return r(),d("div",null,[s[25]||(s[25]=e('<h1 id="使用-elixir-語言編寫一個小遊戲" tabindex="-1">使用 Elixir 語言編寫一個小遊戲 <a class="header-anchor" href="#使用-elixir-語言編寫一個小遊戲" aria-label="Permalink to “使用 Elixir 語言編寫一個小遊戲”">​</a></h1><blockquote><p>通過編寫“猜數字”遊戲來學習 Elixir 編程語言，並將它與一個你熟知的語言做對比。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/12/223351t68886wmza1m9jnt.jpg" alt=""></p><p>為了更好的學習一門新的編程語言，最好的方法是去關注主流語言的一些共有特徵：</p><ul><li>變量</li><li>表達式</li><li>語句</li></ul><p>這些概念是大多數編程語言的基礎。因為這些相似性，只要你通曉了一門編程語言，你可以通過對比差異來熟知另一門編程語言。</p><p>另外一個學習新編程語言的好方法是開始編寫一個簡單標準的程序。它可以讓你集中精力在語言上而非程序的邏輯本身。在這個系列的文章中，我們使用“猜數字”程序來實現，在這個程序中，計算機會選擇一個介於 1 到 100 之間的數字，並要求你來猜測它。程序會循環執行，直到你正確猜出該數字為止。</p><p>“猜數字”這個程序使用了編程語言的以下概念：</p><ul><li>變量</li><li>輸入</li><li>輸出</li><li>條件判斷</li><li>循環</li></ul><p>這是一個學習新編程語言的絕佳實踐。</p><h3 id="猜數字的-elixir-實現" tabindex="-1">猜數字的 Elixir 實現 <a class="header-anchor" href="#猜數字的-elixir-實現" aria-label="Permalink to “猜數字的 Elixir 實現”">​</a></h3>',11)),i("p",null,[p(a,{href:"https://elixir-lang.org/"},{default:l(()=>[...s[0]||(s[0]=[n("Elixir",-1)])]),_:1}),s[2]||(s[2]=n(" 是一門被設計用於構建穩定可維護應用的動態類型的函數式編程語言。它與 ",-1)),p(a,{href:"https://www.erlang.org/"},{default:l(()=>[...s[1]||(s[1]=[n("Erlang",-1)])]),_:1}),s[3]||(s[3]=n(" 運行於同一虛擬機之上，吸納了 Erlang 的眾多長處的同時擁有更加簡單的語法。",-1))]),s[26]||(s[26]=e(`<p>你可以編寫一個 Elixir 版本的“猜數字”遊戲來體驗這門語言。</p><p>這是我的實現方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>defmodule Guess do</span></span>
<span class="line"><span>  def guess() do</span></span>
<span class="line"><span>     random = Enum.random(1..100)</span></span>
<span class="line"><span>     IO.puts &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span>     Guess.guess_loop(random)</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>  def guess_loop(num) do</span></span>
<span class="line"><span>    data = IO.read(:stdio, :line)</span></span>
<span class="line"><span>    {guess, _rest} = Integer.parse(data)</span></span>
<span class="line"><span>    cond do</span></span>
<span class="line"><span>      guess &lt; num -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;Too low!&quot;</span></span>
<span class="line"><span>        guess_loop(num)</span></span>
<span class="line"><span>      guess &gt; num -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;Too high!&quot;</span></span>
<span class="line"><span>        guess_loop(num)</span></span>
<span class="line"><span>      true -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Guess.guess()</span></span></code></pre></div><p>Elixir 通過列出變量的名稱後面跟一個 <code>=</code> 號來為了給變量分配一個值。舉個例子，表達式 <code>random = 0</code> 給 <code>random</code> 變量分配一個數值 0。</p><p>代碼以定義一個模組開始。在 Elixir 語言中，只有模組可以包含命名函數。</p><p>緊隨其後的這行代碼定義了入口函數 <code>guess()</code>，這個函數：</p><ul><li>調用 <code>Enum.random()</code> 函數來獲取一個隨機整數</li><li>打印遊戲提示</li><li>調用循環執行的函數</li></ul><p>剩餘的遊戲邏輯實現在 <code>guess_loop()</code> 函數中。</p>`,8)),i("p",null,[s[5]||(s[5]=i("code",null,"guess_loop()",-1)),s[6]||(s[6]=n(" 函數利用 ",-1)),p(a,{href:"https://en.wikipedia.org/wiki/Tail_call"},{default:l(()=>[...s[4]||(s[4]=[n("尾遞歸",-1)])]),_:1}),s[7]||(s[7]=n(" 來實現循環。Elixir 中有好幾種實現循環的方法，尾遞歸是比較常用的一種方式。",-1)),s[8]||(s[8]=i("code",null,"guess_loop()",-1)),s[9]||(s[9]=n(" 函數做的最後一件事就是調用自身。",-1))]),s[27]||(s[27]=e(`<p><code>guess_loop()</code> 函數的第一行讀取用户輸入。下一行調用 <code>parse()</code> 函數將輸入轉換成一個整數。</p><p><code>cond</code> 表達式是 Elixir 版本的多重分支表達式。與其他語言中的 <code>if/elif</code> 或者 <code>if/elsif</code> 表達式不同，Elixir 對於的首個分支或者最後一個沒有分支並沒有區別對待。</p><p>這個 <code>cond</code> 表達式有三路分支：猜測的結果可以比隨機數大、小或者相等。前兩個選項先輸出不等式的方向然後遞歸調用 <code>guess_loop()</code>，循環返回至函數開始。最後一個選項輸出 <code>That&#39;s right</code>，然後這個函數就完成了。</p><h3 id="輸出例子" tabindex="-1">輸出例子 <a class="header-anchor" href="#輸出例子" aria-label="Permalink to “輸出例子”">​</a></h3><p>現在你已經編寫了你的 Elixir 代碼，你可以運行它來玩“猜數字”的遊戲。每次你執行這個程序，Elixir 會選擇一個不同的隨機數，你可以一直猜下去直到你找到正確的答案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ elixir guess.exs</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>30</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>20</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>14</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>“猜數字”遊戲是一個學習一門新編程語言的絕佳入門程序，因為它用了非常直接的方法實踐了常用的幾個編程概念。通過用不同語言實現這個簡單的小遊戲，你可以實踐各個語言的核心概念並且比較它們的細節。</p><p>你是否有你最喜愛的編程語言？你將怎樣用它來編寫“猜數字”這個遊戲？關注這個系列的文章來看看其他你可能感興趣的語言實現。</p><hr>`,9)),i("p",null,[s[11]||(s[11]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/20/12/elixir"},{default:l(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/20/12/elixir",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/moshez"},{default:l(()=>[...s[12]||(s[12]=[n("Moshe Zadka",-1)])]),_:1}),s[17]||(s[17]=n(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 譯者：",-1)),p(a,{href:"https://github.com/tt67wq"},{default:l(()=>[...s[14]||(s[14]=[n("tt67wq",-1)])]),_:1}),s[19]||(s[19]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[n("Linux中國",-1)])]),_:1}),s[24]||(s[24]=n(" 榮譽推出",-1))])])}const c=t(u,[["render",g]]);export{k as __pageData,c as default};
